#include <stdexcept>
#include <string>
#include <cassert>
#include <iostream>

int main() {
    try {
        throw std::runtime_error("Invalid input");
    } catch (const std::runtime_error &error) {
        assert(std::string(error.what()) == "Invalid input");
    }
    std::cout << "Checks passed\n";
}
